import getpass
import os
import json

class PasswordManager:
    def __init__(self, filename='passwords.json'):
        self.filename = filename
        self.passwords = self.load_passwords()

    def load_passwords(self):
        if os.path.exists(self.filename):
            with open(self.filename, 'r') as file:
                return json.load(file)
        return {}

    def save_passwords(self):
        with open(self.filename, 'w') as file:
            json.dump(self.passwords, file)

    def add_password(self, site, username, password):
        self.passwords[site] = { 'username': username, 'password': password }
        self.save_passwords()
        print(f"Password for {site} saved successfully.")

    def get_password(self, site):
        return self.passwords.get(site, None)

    def update_password(self, site, username, new_password):
        if site in self.passwords and self.passwords[site]['username'] == username:
            self.passwords[site]['password'] = new_password
            self.save_passwords()
            print(f"Password for {site} updated successfully.")
        else:
            print("Password update failed. Site or username not found.")

    def delete_password(self, site):
        if site in self.passwords:
            del self.passwords[site]
            self.save_passwords()
            print(f"Password for {site} deleted successfully.")
        else:
            print("Password deletion failed. Site not found.")

    def display_passwords(self):
        for site, credentials in self.passwords.items():
            print(f"{site}: {credentials['username']}")

